--
-- Table structure for table `robot_player_daily_summary`
--

DROP TABLE IF EXISTS `robot_player_daily_summary`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `robot_player_daily_summary` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_group_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `statistics_group_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `business_date` date NOT NULL,
  `business_timestamp` bigint NOT NULL,
  `wxid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nickname` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `display_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `player_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `balance` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `direct_parent_wxid` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direct_parent_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_path` text COLLATE utf8mb4_unicode_ci,
  `level_no` int NOT NULL DEFAULT '1',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `total_flow` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `used_flow` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `remaining_flow` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `agent_pending_flow` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `agent_pending_rebate` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `pending_rebate` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `total_up` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `total_down` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `total_profit_loss` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `rebate_rate` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `rebate_rate_unit` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'per_10000',
  `total_rebate` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `sync_reason` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_robot_daily_event` (`event_id`),
  KEY `idx_robot_daily_player` (`player_group_id`,`wxid`,`business_date`),
  KEY `idx_robot_daily_date` (`player_group_id`,`business_date`)
) ENGINE=InnoDB AUTO_INCREMENT=138 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

