--
-- Table structure for table `robot_player_updown_record`
--

DROP TABLE IF EXISTS `robot_player_updown_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `robot_player_updown_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_group_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `statistics_group_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `database_generation` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `record_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `wxid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nickname` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(20,4) NOT NULL,
  `balance_delta` decimal(20,4) NOT NULL,
  `balance_after` decimal(20,4) NOT NULL,
  `total_up_after` decimal(20,4) NOT NULL,
  `total_down_after` decimal(20,4) NOT NULL,
  `approved_at` bigint NOT NULL,
  `business_timestamp` bigint NOT NULL,
