DROP TABLE IF EXISTS `agent_report_export_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agent_report_export_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_no` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requester_user_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_group_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agent_player_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agent_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `file_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `include_agent_detail` tinyint(1) NOT NULL DEFAULT '0',
  `include_player_detail` tinyint(1) NOT NULL DEFAULT '0',
  `task_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `progress` int NOT NULL DEFAULT '0',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_size` bigint DEFAULT NULL,
  `content_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `row_count` int NOT NULL DEFAULT '0',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `started_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `expires_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_export_task_no` (`task_no`),
  KEY `idx_agent_export_user_time` (`requester_user_id`,`created_at`),
  KEY `idx_agent_export_status` (`task_status`,`created_at`)
